//! Single-threaded zc-ring-x1 spsc v4 round-trip bench, closure
//! (`reserve_slot_with`) API, the segmented ring over a pool.

use std::hint::black_box;

use zc_ring_x1::spsc::v4::{Consumer, Producer};

